-- Tokens are generated by storage, never by source metadata/content hashes.
CREATE TABLE document_revisions (
 document_id TEXT PRIMARY KEY REFERENCES documents(id) ON DELETE CASCADE,
 revision TEXT NOT NULL
);
INSERT INTO document_revisions(document_id,revision)
 SELECT id,lower(hex(randomblob(32))) FROM documents;
ALTER TABLE project_document_scopes ADD COLUMN revision TEXT NOT NULL DEFAULT '';
-- Previous grants did not attest a caller-verified generation. Do not upgrade
-- them silently: trusted ingestion must obtain and assign a new revision.
DELETE FROM project_document_scopes;

CREATE TRIGGER document_revision_insert AFTER INSERT ON documents BEGIN
 INSERT OR REPLACE INTO document_revisions(document_id,revision) VALUES(NEW.id,lower(hex(randomblob(32))));
 DELETE FROM project_document_scopes WHERE document_id=NEW.id;
END;
CREATE TRIGGER document_revision_update AFTER UPDATE ON documents BEGIN
 DELETE FROM document_revisions WHERE document_id=OLD.id;
 INSERT OR REPLACE INTO document_revisions(document_id,revision) VALUES(NEW.id,lower(hex(randomblob(32))));
 DELETE FROM project_document_scopes WHERE document_id=OLD.id OR document_id=NEW.id;
END;
CREATE TRIGGER document_revision_delete AFTER DELETE ON documents BEGIN
 DELETE FROM document_revisions WHERE document_id=OLD.id;
 DELETE FROM project_document_scopes WHERE document_id=OLD.id;
END;
CREATE TRIGGER document_revision_chunk_insert AFTER INSERT ON document_chunks BEGIN
 UPDATE document_revisions SET revision=lower(hex(randomblob(32))) WHERE document_id=NEW.document_id;
END;
CREATE TRIGGER document_revision_chunk_update AFTER UPDATE ON document_chunks BEGIN
 UPDATE document_revisions SET revision=lower(hex(randomblob(32))) WHERE document_id=OLD.document_id OR document_id=NEW.document_id;
END;
CREATE TRIGGER document_revision_chunk_delete AFTER DELETE ON document_chunks BEGIN
 UPDATE document_revisions SET revision=lower(hex(randomblob(32))) WHERE document_id=OLD.document_id;
END;
